{
  "findings": [
    {
      "ref": "[2]",
      "area": "money",
      "claim": "A parent reports that Adobe hides an early termination fee of 50 percent of the remaining monthly payments if you cancel within the first year of an annual plan paid monthly.",
      "stance": "risk",
      "quote": "the ETF | 50 percent of the remaining monthly payments if you cancel in the first year of an annual plan paid monthly"
    },
    {
      "ref": "[2]",
      "area": "money",
      "claim": "A parent reports that Adobe buries the early termination fee in fine print or behind small icons, making it hard to notice.",
      "stance": "risk",
      "quote": "Adobe buried the ETF in fine print or behind small icons on its website"
    },
    {
      "ref": "[2]",
      "area": "money",
      "claim": "A parent reports that Adobe makes the cancellation process unnecessarily complex to deter users from canceling.",
      "stance": "risk",
      "quote": "Adobe's cancellation process is intentionally complex, requiring multiple steps and forcing users to re-enter their password and complete a mandatory feedback page that prominently displays the ETF"
    },
    {
      "ref": "[2]",
      "area": "money",
      "claim": "A parent reports that Adobe continues billing users even after they believe they have canceled their subscription.",
      "stance": "risk",
      "quote": "Consumers also reported continued billing despite believing they had canceled their subscriptions"
    },
    {
      "ref": "[7]",
      "area": "money",
      "claim": "A parent reports that the settlement requires Adobe to give subscribers easy ways to cancel and to clearly disclose any early termination fee before enrollment.",
      "stance": "mitigation",
      "quote": "the order requires Adobe to give subscribers easy ways to cancel and clearly disclose any early termination fee and how it is calculated before enrolling customers"
    },
    {
      "ref": "[7]",
      "area": "money",
      "claim": "A parent reports that Adobe must send a reminder before a free trial longer than seven days converts to a paid plan with an early termination fee.",
      "stance": "mitigation",
      "quote": "For free trials longer than seven days, it must also send a reminder before the paid plan starts"
    },
    {
      "ref": "[3]",
      "area": "money",
      "claim": "A parent reports that Adobe's subscription terms and refund policy are explained on its own website.",
      "stance": "neutral",
      "quote": "Adobe's own page explains its subscription terms and refund policy"
    },
    {
      "ref": "[4]",
      "area": "neutral",
      "claim": "A parent reports that Adobe denies wrongdoing and says it is transparent with subscription terms and has a simple cancellation process.",
      "stance": "neutral",
      "quote": "We are transparent with the terms and conditions of our subscription agreements and have a simple cancellation process. We will refute FTC's claims in court."
    },
    {
      "ref": "[1]",
      "area": "neutral",
      "claim": "A parent reports that the FTC complaint alleges Adobe's practices violate the Restore Online Shoppers' Confidence Act (ROSCA).",
      "stance": "neutral",
      "quote": "The complaint accuses Adobe of deceptive practices related to its subscription plans, specifically failing to disclose early termination fees and making the cancellation process unnecessarily complicated"
    },
    {
      "ref": "[1]",
      "area": "neutral",
      "claim": "A parent reports that the FTC complaint alleges Adobe's cancellation process is intentionally complex to deter consumers from canceling.",
      "stance": "risk",
      "quote": "The complaint also describes Adobe's cancellation process as intentionally complex, designed to deter consumers from canceling their subscriptions"
    },
    {
      "ref": "[1]",
      "area": "neutral",
      "claim": "A parent reports that the FTC seeks a permanent injunction, monetary penalties, restitution, and possible contract modifications against Adobe.",
      "stance": "risk",
      "quote": "The complaint seeks a permanent injunction to stop ongoing violations, monetary civil penalties, restitution for affected consumers, and the cancellation or modification of existing contracts entered into under deceptive terms"
    },
    {
      "ref": "[8]",
      "area": "neutral",
      "claim": "A parent reports that Adobe disagrees with the government's claims and denies any wrongdoing.",
      "stance": "neutral",
      "quote": "Adobe said it disagrees with the government's claims and denies any wrongdoing"
    }
  ]
}
